import random
import time


def backoff_delays(attempts: int, base: float = 0.5, cap: float = 30.0):
    for attempt in range(attempts):
        yield min(cap, base * 2**attempt) * random.uniform(0.5, 1.5)


def retry(fn, attempts: int = 5):
    last_error = None
    for delay in backoff_delays(attempts):
        try:
            return fn()
        except ConnectionError as exc:
            last_error = exc
            time.sleep(delay)
    raise last_error

